import { AbstractSystem } from './AbstractSystem.ts';

import type { Context } from '../Context.ts';
import type { PriorityLevel } from './SchedulerSystem.ts';


/** Message sent from main thread → worker */
interface WorkerRequest {
  id: number;
  listenerID: ListenerID;
  data: unknown;
}

/** Message sent from worker → main thread */
interface WorkerResponse {
  id: number;
  result?: unknown;
  error?: string;
}

/** Pending worker request awaiting a response */
interface PendingWorkerRequest {
  resolve: (value: unknown) => void;
  reject: (reason: unknown) => void;
  /** The Worker that owns this request (for targeted cancel messages) */
  worker: Worker;
  /** Cleanup function to remove AbortSignal listener, if any */
  signalCleanup: (() => void) | null;
  /** When set, resolution is deferred through SchedulerSystem instead of resolving immediately */
  resultPriority: PriorityLevel | null;
}

/** Options for `dispatch()` */
export interface DispatchOptions {
  /**
   * When set, the returned promise is resolved through SchedulerSystem
   * at the given priority instead of resolving immediately in the
   * worker's `onmessage` handler.
   *
   * This prevents worker results from triggering heavy synchronous
   * microtask chains (entity construction, graph rebase, etc.) that
   * blow the frame budget.  Each deferred result gets its own slot in
   * the scheduler's drain loop, allowing the frame to yield between
   * results.
   *
   * When `SchedulerSystem` is unavailable (tests, CLI), the result
   * resolves immediately — no worse than the current behavior.
   *
   * If `SchedulerSystem` later cancels queued deferred work (for example,
   * during reset), the dispatch promise rejects with `AbortError`.
   * Callers should treat this as an expected cancellation path.
   */
  resultPriority?: PriorityLevel;
}

/** Default max worker pool size */
const DEFAULT_MAX_WORKERS = 2;


/**
 * `WorkerSystem` manages the web worker pool and listener function registry.
 *
 * Responsibilities:
 * - **Worker pool** — Spawns module-type workers lazily (on first task),
 *   round-robins tasks across them, terminates on reset.
 * - **listeners** — Code can register listener functions.
 *   These functions can run either in the worker or on the main thread as a fallback.
 *
 * This system has no required dependencies and should be available very early.
 * Design rationale:
 * - `SchedulerSystem` = **when** to run (game loop, queues, timers, backpressure)
 * - `WorkerSystem` = **where** to run (worker pool, task dispatch, listener registry)
 * - `NetworkSystem` = network I/O (fetch lifecycle, inflight tracking, dedup, concurrency)
 *
 * Events available:
 * - `paused`  - Fires when the system transitions from unpaused to paused
 * - `resumed` - Fires when the system transitions from paused to unpaused
 */
export class WorkerSystem extends AbstractSystem {

  // Worker pool
  /** URL to the worker script (set by host app via `workerURL` setter) */
  protected _workerURL: string | null;
  /** Pool of spawned workers */
  protected _workers: Worker[];
  /** Maximum number of workers to spawn */
  protected _maxWorkers: number;
  /** Round-robin index for dispatching tasks to workers */
  protected _workerIndex: number;
  /** Monotonically increasing request ID for correlating responses */
  protected _nextRequestID: number;
  /** Pending requests awaiting worker responses, keyed by request ID */
  protected _pendingRequests: Map<number, PendingWorkerRequest>;

  // listener registry
  /** Registered listeners for worker/main-thread dispatch */
  protected _listeners: Map<ListenerID, Listener>;


  /**
   * @param context - Global shared application context
   */
  public constructor(context: Context) {
    super(context);
    this.id = 'worker';
    this.requiredDependencies = new Set<SystemID>();
    this.optionalDependencies = new Set<SystemID>(['scheduler']);

    // Set a default value for _workerURL here.
    // We expect to find a 'rapid-worker.js' file alongside the main 'rapid.js' file.
    // Host apps can override this value or disable workers completely by setting
    // `worker.workerURL = null` after construction time
    const scriptURL = context.scriptURL;
    if (scriptURL) {
      const dir = scriptURL.substring(0, scriptURL.lastIndexOf('/') + 1);
      const isMin = scriptURL.includes('.min.');
      this._workerURL = dir + (isMin ? 'rapid-worker.min.js' : 'rapid-worker.js');
    } else {
      this._workerURL = null;
    }

    this._workers = [];
    this._maxWorkers = DEFAULT_MAX_WORKERS;
    this._workerIndex = 0;
    this._nextRequestID = 1;
    this._pendingRequests = new Map<number, PendingWorkerRequest>();
    this._listeners = new Map<ListenerID, Listener>();
  }


  /**
   * Called after all core objects have been constructed.
   * @return Promise resolved when this component has completed initialization
   */
  public initAsync(): Promise<void> {
    if (this._initPromise) return this._initPromise;
    return this._initPromise = super.initAsync();
  }


  /**
   * Called after all core objects have been initialized.
   * @return Promise resolved when this component has completed startup
   */
  public startAsync(): Promise<void> {
    if (this._startPromise) return this._startPromise;
    return this._startPromise = super.startAsync();
  }


  /**
   * Called after completing an edit session to reset any internal state.
   * @return Promise resolved when this component has completed resetting
   */
  public resetAsync(): Promise<void> {
    return Promise.resolve();
  }


  // -------------------------------------------------------
  // Worker pool
  //
  // Spawns web workers lazily (on first task) up to `maxWorkers`.
  // Tasks are dispatched round-robin.  Each request gets a unique
  // ID; the worker posts back a response with the same ID so the
  // system can resolve the correct Promise.
  //
  // `workerURL` is auto-detected from the Rapid script URL during
  // `prepareAsync()`.  Host apps can override or set to null.
  // Workers are terminated on `resetAsync()` and `terminateWorkers()`.
  // -------------------------------------------------------

  /**
   * URL to the built worker script.  Auto-detected from the Rapid bundle
   * location during `prepareAsync()`.  Override with a custom URL, or set
   * to `null` to disable worker offloading.
   * @return  Worker script URL, or `null` if workers are disabled
   */
  public get workerURL(): string | null {
    return this._workerURL;
  }
  /**
   * Sets the URL for the worker script; pass null to disable worker offloading.
   * @param url - URL string for the worker script, or `null` to disable
   */
  public set workerURL(url: string | null) {
    this._workerURL = url;
  }


  /**
   * Maximum number of workers in the pool.  Workers are spawned
   * lazily, so setting this higher doesn't immediately spawn them.
   * Defaults to 2.
   * @return  Maximum worker pool size
   */
  public get maxWorkers(): number {
    return this._maxWorkers;
  }
  /**
   * Sets the maximum number of workers in the pool (minimum 1).
   * @param n - Maximum pool size; values below 1 are clamped to 1
   */
  public set maxWorkers(n: number) {
    this._maxWorkers = Math.max(1, n);
  }


  /**
   * Number of workers currently alive in the pool.
   * @return  Current number of live workers
   * @readonly
   */
  public get numWorkers(): number {
    return this._workers.length;
  }


  /**
   * Number of worker requests awaiting a response.
   * Useful for debugging and tests.
   * @return  Count of pending worker requests
   * @readonly
   */
  public get numPendingRequests(): number {
    return this._pendingRequests.size;
  }


  /**
   * Dispatches a message to a given web worker listener function
   * and returns a Promise that resolves with the worker's result.
   *
   * The `data` argument must be structured-clone-compatible
   * (no functions, DOM nodes, or non-transferable objects).
   *
   * An optional `AbortSignal` can be passed to cancel the task.
   * When the signal fires, a `{ type: 'cancel', id }` message is
   * sent to the worker, the pending promise rejects with an AbortError,
   * and the worker-side AbortController is triggered.
   *
   * If `options.resultPriority` is provided, result delivery may be deferred
   * through SchedulerSystem. If that deferred task is cancelled before running
   * (for example during scheduler reset), this promise also rejects with
   * `AbortError`. Callers should handle `AbortError` as expected cancellation.
   *
   * @param listenerID - The id of the listener function
   * @param data - Serializable input for the listener
   * @param signal - Optional AbortSignal to cancel the task
   * @param options - Optional dispatch options (e.g. deferred result priority)
   * @return Promise resolved with the task result, or rejected on error/cancellation
   * @throws Error if `workerURL` has not been set
   */
  public dispatch<T = unknown>(
    listenerID: ListenerID,
    data?: unknown, signal?: AbortSignal,
    options?: DispatchOptions
  ): Promise<T> {
    if (!this._workerURL) {
      return Promise.reject(new Error('WorkerSystem: workerURL not set'));
    }

    // Already aborted before we even start
    if (signal?.aborted) {
      const err = new Error('The operation was aborted.');
      err.name = 'AbortError';
      return Promise.reject(err);
    }

    const worker = this._getOrSpawnWorker();
    const id = this._nextRequestID++;

    return new Promise<T>((resolve, reject) => {
      let signalCleanup: (() => void) | null = null;

      if (signal) {
        const onAbort = () => {
          // Send cancel to the specific worker that owns this request
          worker.postMessage({ type: 'cancel', id });
          // Clean up and reject
          const pending = this._pendingRequests.get(id);
          if (pending) {
            pending.signalCleanup = null;  // prevent double cleanup
            this._pendingRequests.delete(id);
            const err = new Error('The operation was aborted.');
            err.name = 'AbortError';
            reject(err);
          }
        };
        signal.addEventListener('abort', onAbort, { once: true });
        signalCleanup = () => signal.removeEventListener('abort', onAbort);
      }

      this._pendingRequests.set(id, {
        resolve: resolve as (value: unknown) => void,
        reject,
        worker,
        signalCleanup,
        resultPriority: options?.resultPriority ?? null,
      });

      const request: WorkerRequest = { id, listenerID, data };
      worker.postMessage(request);
    });
  }


  /**
   * Terminates all workers in the pool and rejects any pending
   * requests.  Called automatically by `resetAsync()`.
   */
  public terminateWorkers(): void {
    for (const worker of this._workers) {
      worker.terminate();
    }
    this._workers.length = 0;
    this._workerIndex = 0;

    // Reject all pending requests and clean up signal listeners
    for (const [, pending] of this._pendingRequests) {
      if (pending.signalCleanup) pending.signalCleanup();
      pending.reject(new Error('WorkerSystem: worker terminated'));
    }
    this._pendingRequests.clear();
  }


  /**
   * Registers a named listener function.
   * @param listenerID - The id of the listener function
   * @param listener - Listener function
   */
  public registerListener(listenerID: ListenerID, listener: Listener): void {
    this._listeners.set(listenerID, listener);
  }


  /**
   * Removes a previously registered listener function.
   * @param listenerID - The id of the listener function
   */
  public unregisterListener(listenerID: ListenerID): void {
    this._listeners.delete(listenerID);
  }


  /**
   * Returns the listener function for a given listenerID, or undefined.
   * @param listenerID - The id of the listener function
   * @return The listener function, or undefined if no such id exists
   */
  public getListener(listenerID: ListenerID): Listener | undefined {
    return this._listeners.get(listenerID);
  }


  /**
   * Returns the next worker from the pool (round-robin), spawning
   * a new one if the pool isn't full yet.
   * @return  The worker to use for the next request
   */
  protected _getOrSpawnWorker(): Worker {
    // Spawn if pool not full
    if (this._workers.length < this._maxWorkers) {
      const worker = this._spawnWorker();
      this._workers.push(worker);
    }

    // Round-robin
    const worker = this._workers[this._workerIndex % this._workers.length];
    this._workerIndex++;
    return worker;
  }


  /**
   * Resolves the configured `workerURL` into a URL that is safe to pass to the
   * `Worker` constructor, transparently handling cross-origin worker hosting.
   *
   * ## Why this is needed
   * The browser lets a page load its *main* script bundle (`rapid.js`) from any
   * origin via `<script src>`, but the `Worker` constructor requires the
   * worker's **top-level** script to be **same-origin** with the document —
   * for both classic *and* module workers.  This is a hard rule and is **not**
   * relaxable with CORS response headers.
   *
   * That matters because host apps commonly serve the Rapid bundle from a CDN /
   * object store (Azure Blob Storage, S3, etc.) on a *different* origin than the
   * app itself.  In that setup `workerURL` is auto-detected (see the
   * constructor) as `https://<cdn-origin>/…/rapid-worker.js`, and
   * `new Worker(thatURL, { type: 'module' })` throws a SecurityError.
   *
   * ## The fix
   * When (and only when) `workerURL` resolves to a **cross-origin http(s)** URL,
   * we build a tiny **same-origin** module via `Blob` + `URL.createObjectURL`
   * whose entire body is a single static `import` of the real cross-origin
   * worker module:
   *
   * ```js
   * import "https://<cdn-origin>/…/rapid-worker.js";
   * ```
   *
   * The `Worker` top-level script is now same-origin (a `blob:` URL, which
   * inherits the document's origin), satisfying the constructor.  Because it's a
   * **module** worker, the cross-origin `import` inside it *is* permitted
   * (subject to normal CORS on the CDN response), and — crucially — the imported
   * module's own relative imports, `import.meta.url`, and any wasm/asset fetches
   * all resolve against the **real** CDN origin, exactly as intended.
   *
   * ## What the host still needs
   * - **CORS** on the asset origin (e.g. `Access-Control-Allow-Origin`) so the
   *   `import` and downstream asset fetches succeed.
   * - A **CSP** that permits `worker-src blob:` and `script-src`/`connect-src`
   *   for the CDN origin.  (Rapid's own example pages already ship
   *   `worker-src 'self' blob:` — see `scripts/content_security_policy.ts`.)
   *
   * ## What is intentionally left untouched
   * Same-origin URLs and non-http(s) schemes (`file:`, `blob:`, `data:`) are
   * returned as-is — they are already valid worker top-level scripts and need no
   * shim.  This also keeps the behavior a no-op for the test/headless harness,
   * which spawns workers from a local `file:` URL.
   *
   * Note: the created `blob:` URL is intentionally **not** revoked here.  A
   * module worker fetches its top-level script asynchronously, so revoking
   * eagerly would risk a "Failed to fetch" race.  At most `maxWorkers` (default
   * 2) such URLs are ever created per session, so the leak is negligible.
   *
   * @param   workerURL - The configured worker script URL
   * @return  A same-origin-safe URL to hand to the `Worker` constructor
   */
  protected _resolveWorkerURL(workerURL: string): string {
    // Without a document origin to compare against (non-browser/headless host)
    // we can't classify cross-origin, so pass the URL through unchanged.
    if (typeof location === 'undefined' || !location.href) {
      return workerURL;
    }

    let abs: URL;
    try {
      abs = new URL(workerURL, location.href);
    } catch {
      return workerURL;  // not a URL we can reason about; leave it alone
    }

    const isSameOrigin = abs.origin === location.origin;
    const isHttp = abs.protocol === 'http:' || abs.protocol === 'https:';

    // Only cross-origin http(s) workers hit the same-origin restriction.
    if (isSameOrigin || !isHttp) {
      return workerURL;
    }

    const shim = `import ${JSON.stringify(abs.href)};`;
    return URL.createObjectURL(new Blob([shim], { type: 'text/javascript' }));
  }


  /**
   * Creates a new Worker and wires up message/error handlers.
   *
   * Deferred result delivery failures (including scheduler-triggered `AbortError` cancellations)
   * are propagated to the original dispatch caller via `pending.reject(...)`.
   * @return  The newly created worker
   */
  protected _spawnWorker(): Worker {
    const scheduler = this.context.systems.scheduler;
    const worker = new Worker(this._resolveWorkerURL(this._workerURL!), { type: 'module' });

    worker.onmessage = (event: MessageEvent<WorkerResponse>) => {
      const { id, result, error } = event.data;
      const pending = this._pendingRequests.get(id);
      if (!pending) return;  // stale response after terminate or cancel
      this._pendingRequests.delete(id);

      if (pending.signalCleanup) pending.signalCleanup();

      if (error !== undefined) {
        pending.reject(new Error(error));
      } else if (scheduler && pending.resultPriority) {
        // Defer resolution through SchedulerSystem
        scheduler
          .schedule(() => pending.resolve(result), { priority: pending.resultPriority })
          .catch(err => { pending.reject(err); });
      } else {
        pending.resolve(result);  // fallback: resolve immediately
      }
    };

    worker.onerror = (event: ErrorEvent) => {
      console.error('WorkerSystem: worker error:', event.message);  // eslint-disable-line no-console
    };

    return worker;
  }
}
