import { selection } from 'd3-selection';

import { AbstractUiCard } from './AbstractUiCard.ts';
import { uiIcon } from '../icon.ts';
import { utilCmd } from '../../util/cmd.ts';

import type { Context } from '../../Context.ts';
import type { D3Selection } from 'd3-selection';


/**
 * `UiLocationCard` shows the coordinates and reverse-geocoded place name at the mouse location.
 */
export class UiLocationCard extends AbstractUiCard {
  public id: string;

  protected _currLocation: string | null;
  protected _keys: string[] | null;
  public rerender: () => void;
  protected _deferredUpdateLocation: (loc: any) => void;


  /**
   * @param  context - Global shared application context
   */
  public constructor(context: Context) {
    super(context);
    this.id = 'location';

    const eventManager = context.systems.gfx!.eventManager!;
    const l10n = context.systems.l10n!;
    const scheduler = context.systems.scheduler;  // optional

    this._currLocation = null;
    this._keys = null;

    // Ensure methods used as callbacks always have `this` bound correctly.
    // (This is also necessary when using `d3-selection.call`)
    this.render = this.render.bind(this);
    this.rerender = () => this.render();
    this.updateLocation = this.updateLocation.bind(this);
    this._deferredUpdateLocation = (loc) => {
      // scheduler throttles to no more than 1/sec; without it, just update immediately
      if (scheduler) {
        scheduler.debounce('UiLocationCard-updateLocation', () => this.updateLocation(loc), { ms: 1000 });
      } else {
        this.updateLocation(loc);
      }
    };
    this._setupKeybinding = this._setupKeybinding.bind(this);

    // Event listeners
    eventManager.on('pointermove', this.rerender);
    l10n.on('localechange', this._setupKeybinding);

    this._setupKeybinding();
  }


  /**
   * Accepts a parent selection, and renders the content under it.
   * (The parent selection is required the first time, but can be inferred on subsequent renders)
   * @param $parent - A d3-selection to a HTMLElement that this component should render itself into
   */
  public override render($parent: D3Selection | null = this.$parent): void {
    if ($parent instanceof selection) {
      this.$parent = $parent;
    } else {
      return;   // no parent - called too early?
    }

    if (!this.visible) return;

    const context = this.context;
    const l10n = context.systems.l10n!;
    const map = context.systems.map!;
    const loc = map.mouseLoc();    // Mouse coordinates as [lon,lat]

    // .card-container
    let $wrap: D3Selection = $parent.selectAll('.card-container')
      .data([this.id], d => d);

    // enter
    const $$wrap = $wrap.enter()
      .append('div')
      .attr('class', d => `fillD2 card-container card-container-${d}`);

    const $$title = $$wrap
      .append('div')
      .attr('class', 'fillD2 card-title');

    $$title
      .append('h3');

    $$title
      .append('button')
      .attr('class', 'close')
      .on('click', this.toggle)
      .call(uiIcon('#rapid-icon-close'));

    $$wrap
      .append('div')
      .attr('class', d => `card-content card-content-${d}`);


    // update
    this.$wrap = $wrap = $wrap.merge($$wrap);

    $wrap.selectAll('h3')
      .text(l10n.t('text.location'));

    // .card-content
    const $content = $wrap.selectAll('.card-content');

    // If the user is trying to select text, don't redraw - Rapid#1659
    const textSelection = document.getSelection();
    if (textSelection?.containsNode($content.node() as Node, true)) return;

    // Empty out the DOM content and rebuild from scratch..
    $content.html('');


    const $list = $content
      .append('ul');

    // Append coordinates of mouse
    $list
      .append('li')
      .text(l10n.dmsCoordinatePair(loc))
      .append('li')
      .text(l10n.decimalCoordinatePair(loc));

    // Append reverse geolocated placename
    $content
      .append('div')
      .attr('class', 'location-info')
      .text(this._currLocation || ' ');

    this._deferredUpdateLocation(loc);
  }


  /**
   * Performs a reverse geolocation lookup to get the name of the place for the given loc
   * Then updates the `.location-info` div in the panel.
   * @param loc -  coordinates to lookup as [lon,lat]
   */
  public updateLocation(loc: any): void {
    if (!this.visible) return;
    if (!this.$wrap) return;   // called too early?

    const context = this.context;
    const l10n = context.systems.l10n!;
    const nominatim = context.services.nominatim;
    const $content = this.$wrap.selectAll('.card-content');

    if (nominatim) {
      nominatim.reverse(loc, (err: any, result: any) => {
        this._currLocation = result ? result.display_name : l10n.t('info_panels.location.unknown_location');
        $content.selectAll('.location-info')
          .text(this._currLocation);
      });
    } else {
      this._currLocation = l10n.t('info_panels.location.unknown_location');
      $content.selectAll('.location-info')
        .text(this._currLocation);
    }
  }


  /**
   * This sets up the keybinding, replacing existing if needed
   */
  protected _setupKeybinding(): void {
    const context = this.context;
    const keyboard = context.systems.keyboard!;
    const l10n = context.systems.l10n!;

    if (Array.isArray(this._keys)) {
      keyboard.global.off(this._keys);
    }

    this._keys = [utilCmd('⌘⇧' + l10n.t('shortcuts.command.toggle_location_card.key'))];
    keyboard.global.on(this._keys, this.toggle);
  }

}
