import { AbstractBehavior } from './AbstractBehavior.ts';

import type { AbstractOperation } from '../operations/AbstractOperation.ts';
import type { Context } from '../Context.ts';
import type { KeyboardSystem } from '../core/KeyboardSystem.ts';


/**
 * `KeyOperationBehavior` binds whatever keystroke events trigger an "operation"
 * ("operations" are the things that go on the editing menu)
 */
export class KeyOperationBehavior extends AbstractBehavior {

  /** The operation this behavior is associated with */
  protected _operation: AbstractOperation;
  /** The keyboard system, for document-level key events */
  protected _keyboard: KeyboardSystem | null;


  /**
   * @param  context - Global shared application context
   * @param  operation - The operation this behavior is associated with
   */
  public constructor(context: Context, operation: AbstractOperation) {
    super(context);
    this.id = `key-${operation.id}`;

    this._operation = operation;
    this._keyboard = null;

    const isTestEnvironment = (!('window' in globalThis)) || ('assert' in globalThis) || ('expect' in globalThis);
    if (!isTestEnvironment) {
      this._keyboard = this.context.systems.keyboard ?? null; // "global" keybinding (on document)
    }

    // Make sure the event handlers have `this` bound correctly
    this._keydown = this._keydown.bind(this);
  }


  /**
   * Bind event handlers
   */
  public enable(): void {
    if (this._enabled) return;

    const operation = this._operation;
    if (operation.available() && operation.keys && this._keyboard) {
      this._keyboard.global.on(operation.keys, this._keydown);
      this._enabled = true;
    }
  }


  /**
   * Unbind event handlers
   */
  public disable(): void {
    if (!this._enabled) return;
    this._enabled = false;

    const operation = this._operation;
    if (operation.keys && this._keyboard) {
      this._keyboard.global.off(operation.keys);
    }
  }


  /**
   * Handles the keydown event
   * @param  e - A d3 keydown event
   */
  protected _keydown(e: KeyboardEvent): void {
    const context = this.context;
    const operation = this._operation;
    const ui = context.systems.ui!;

    if (!operation.availableForKeypress()) return;  // copy paste detail 😕

    e.preventDefault();

    const disabled = operation.disabled();

    if (disabled) {
      ui.Flash.show({
        duration: 4000,
        iconName: `#rapid-operation-${operation.id}`,
        iconClass: 'operation disabled',
        label: operation.tooltip()
      });

    } else {
      ui.Flash.show({
        duration: 2000,
        iconName: `#rapid-operation-${operation.id}`,
        iconClass: 'operation',
        label: operation.annotation() || operation.title
      });

      operation.point(null);  // copy-paste detail 😕
      operation.run();  // do the thing
    }
  }

}
