import { selection } from 'd3-selection';
import { uiIcon } from './icon.ts';
import { UiDataHeader } from './UiDataHeader.ts';
import { UiSectionRawTagEditor } from './sections/UiSectionRawTagEditor.ts';
import { utilObjectOmit } from '@rapid-sdk/util';

import type { Context } from '../Context.ts';
import type { D3Selection } from 'd3-selection';


/**
 * `UiDataEditor` renders the sidebar editor for custom/vector map data features.
 * Set the feature to display via the public `datum` property, then call `.render($parent)`.
 */
export class UiDataEditor {
  public context: Context;
  public datum: any;

  // Child components
  public DataHeader: UiDataHeader;
  public RawTagEditor: UiSectionRawTagEditor;

  // D3 selections
  public $parent: D3Selection | null;


  /**
   * @param  context - Global shared application context
   */
  public constructor(context: Context) {
    this.context = context;
    this.datum = null;

    this.DataHeader = new UiDataHeader(context);
    this.RawTagEditor = new UiSectionRawTagEditor(context, 'custom-data-tag-editor')
      .readOnlyTags([/./]);

    // D3 selections
    this.$parent = null;

    // Ensure methods used as callbacks always have `this` bound correctly.
    this.render = this.render.bind(this);
  }


  /**
   * Accepts a parent selection, and renders the content under it.
   * (The parent selection is required the first time, but can be inferred on subsequent renders)
   * @param $parent - A d3-selection to a HTMLElement that this component should render itself into
   */
  public render($parent: D3Selection | null = this.$parent): void {
    if ($parent instanceof selection) {
      this.$parent = $parent;
    } else {
      return;   // no parent - called too early?
    }

    const context = this.context;
    const l10n = context.systems.l10n!;

    let $heading: D3Selection = $parent.selectAll('.heading')
      .data([0]);

    const $$heading = $heading.enter()
      .append('div')
      .attr('class', 'heading fillL');

    $$heading
      .append('button')
      .attr('class', 'close')
      .on('click', () => context.enter('browse'))
      .call(uiIcon('#rapid-icon-close'));

    $$heading
      .append('h3');

    // update
    $heading = $heading.merge($$heading);

    $heading.select('h3')
      .text(l10n.t('map_data.title'));


    let $body: D3Selection = $parent.selectAll('.body')
      .data([0]);

    $body = $body.enter()
      .append('div')
      .attr('class', 'body')
      .merge($body);

    const $editor: D3Selection = $body.selectAll('.data-editor')
      .data([0]);

    // enter/update
    this.DataHeader.datum = this.datum;
    $editor.enter()
      .append('div')
      .attr('class', 'modal-section data-editor')
      .merge($editor)
      .call(this.DataHeader.render);

    const $rawTagEditor: D3Selection = $body.selectAll('.data-tag-editor')
      .data([0]);

    // enter/update
    $rawTagEditor.enter()
      .append('div')
      .attr('class', 'data-tag-editor')
      .merge($rawTagEditor)
      .call(this.RawTagEditor
        .tags((this.datum?.properties) || {})
        .state('hover')
        .render
      )
      .selectAll('textarea.tag-text')
      .attr('readonly', true)
      .classed('readonly', true);


// DEBUG
    const props = utilObjectOmit(this.datum?.props ?? {}, ['geojson']);
    const propsStr = Object.entries(props).reduce((acc, item) => {
      const line = `${item[0]} = ${item[1]}\n`;
      return acc += line;
    }, '');

    const $propInspector = $body.selectAll('.data-prop-inspector')
      .data([this.datum], (d: any) => d.id);

    $propInspector.exit()
      .remove();

    $propInspector.enter()
      .append('pre')
      .attr('class', 'data-prop-inspector')
      .text(propsStr);
  }
}
